import test from 'node:test';
import assert from 'node:assert/strict';
import { roundCents, formatEuros, parseEuros, RATES, convert, formatMoney } from '../src/money.js';

test('roundCents: half to even - 124.5 rounds to 124', () => {
  assert.equal(roundCents(124.5), 124);
});

test('roundCents: half to even - 125.5 rounds to 126', () => {
  assert.equal(roundCents(125.5), 126);
});

test('roundCents: rounds down', () => {
  assert.equal(roundCents(2.4), 2);
});

test('roundCents: rounds up', () => {
  assert.equal(roundCents(2.6), 3);
});

test('roundCents: negative 0.5 rounds to 0', () => {
  assert.equal(roundCents(-0.5), 0);
});

test('formatEuros: positive amount', () => {
  assert.equal(formatEuros(123456), '€1,234.56');
});

test('formatEuros: negative amount', () => {
  assert.equal(formatEuros(-5), '-€0.05');
});

test('parseEuros: simple amount', () => {
  const result = parseEuros('12');
  assert.equal(result.ok, true);
  assert.equal(result.value, 1200);
});

test('parseEuros: with decimal', () => {
  const result = parseEuros('12.5');
  assert.equal(result.ok, true);
  assert.equal(result.value, 1250);
});

test('parseEuros: with thousands separator', () => {
  const result = parseEuros('1,234.56');
  assert.equal(result.ok, true);
  assert.equal(result.value, 123456);
});

test('parseEuros: invalid format', () => {
  const result = parseEuros('abc');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'AMOUNT_INVALID');
});

// RATES tests
test('RATES: EUR is 1', () => {
  assert.equal(RATES.EUR, 1);
});

test('RATES: USD is 1.085', () => {
  assert.equal(RATES.USD, 1.085);
});

test('RATES: GBP is 0.8425', () => {
  assert.equal(RATES.GBP, 0.8425);
});

// convert() tests
test('convert: EUR to EUR', () => {
  const result = convert(10000, 'EUR');
  assert.equal(result.ok, true);
  assert.equal(result.value, 10000);
});

test('convert: EUR to USD', () => {
  const result = convert(10000, 'USD');
  assert.equal(result.ok, true);
  // 10000 * 1.085 = 10850
  assert.equal(result.value, 10850);
});

test('convert: EUR to GBP', () => {
  const result = convert(10000, 'GBP');
  assert.equal(result.ok, true);
  // 10000 * 0.8425 = 8425
  assert.equal(result.value, 8425);
});

test('convert: unknown currency', () => {
  const result = convert(10000, 'JPY');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_CURRENCY');
});

test('convert: zero amount', () => {
  const result = convert(0, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 0);
});

test('convert: negative amount', () => {
  const result = convert(-10000, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, -10850);
});

test('convert: rounds to cents', () => {
  const result = convert(1, 'USD');
  assert.equal(result.ok, true);
  // 1 * 1.085 = 1.085, rounds to 1
  assert.equal(result.value, 1);
});

test('convert: rounding example 2', () => {
  const result = convert(1000, 'GBP');
  assert.equal(result.ok, true);
  // 1000 * 0.8425 = 842.5, rounds to 842 (banker's rounding, 842 is even)
  assert.equal(result.value, 842);
});

test('convert: large amount', () => {
  const result = convert(1000000, 'USD');
  assert.equal(result.ok, true);
  // 1000000 * 1.085 = 1085000
  assert.equal(result.value, 1085000);
});

// formatMoney() tests
test('formatMoney: EUR format', () => {
  assert.equal(formatMoney(123456, 'EUR'), '€1,234.56');
});

test('formatMoney: USD format', () => {
  assert.equal(formatMoney(123456, 'USD'), '$1,234.56');
});

test('formatMoney: GBP format', () => {
  assert.equal(formatMoney(123456, 'GBP'), '£1,234.56');
});

test('formatMoney: negative EUR', () => {
  assert.equal(formatMoney(-5, 'EUR'), '-€0.05');
});

test('formatMoney: negative USD', () => {
  assert.equal(formatMoney(-5, 'USD'), '-$0.05');
});

test('formatMoney: negative GBP', () => {
  assert.equal(formatMoney(-5, 'GBP'), '-£0.05');
});

test('formatMoney: zero', () => {
  assert.equal(formatMoney(0, 'USD'), '$0.00');
});

test('formatMoney: small amount', () => {
  assert.equal(formatMoney(50, 'USD'), '$0.50');
});

test('formatMoney: large amount', () => {
  assert.equal(formatMoney(1000000, 'USD'), '$10,000.00');
});

test('formatMoney: thousands separator', () => {
  assert.equal(formatMoney(123456789, 'USD'), '$1,234,567.89');
});

test('formatMoney: EUR with thousands', () => {
  assert.equal(formatMoney(123456789, 'EUR'), '€1,234,567.89');
});

test('formatMoney: GBP with thousands', () => {
  assert.equal(formatMoney(123456789, 'GBP'), '£1,234,567.89');
});

test('formatMoney: two decimal places always', () => {
  assert.equal(formatMoney(100, 'USD'), '$1.00');
  assert.equal(formatMoney(5, 'USD'), '$0.05');
});

test('formatMoney: unknown currency returns empty', () => {
  assert.equal(formatMoney(100, 'JPY'), '0.00');
});

